BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create function pg_temp.i(n int)returns uuid language sql immutable as $$select('ee710000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create temp table st(k text primary key,v jsonb);grant all on st,assertion_count to service_role;
insert into public.organizations(id,name)values(pg_temp.i(1),'BI query SQL fixture'),(pg_temp.i(2),'BI query other fixture');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)select pg_temp.i(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','bi-query-'||n||'@fixture.invalid',clock_timestamp(),clock_timestamp(),clock_timestamp()from generate_series(101,104)n;
insert into public.profiles(id,org_id,role)select pg_temp.i(n),pg_temp.i(case when n=103 then 2 else 1 end),case when n=102 then'viewer'else'admin'end from generate_series(101,104)n on conflict(id)do update set org_id=excluded.org_id,role=excluded.role;
insert into public.properties(id,org_id,name)values(pg_temp.i(201),pg_temp.i(1),'BI query SQL property'),(pg_temp.i(202),pg_temp.i(2),'BI query other property');
insert into public.fact_marketing_performance(property_id,date,channel_id,source_account_id,currency_code,campaign_id,impressions,clicks,spend,conversions)values(pg_temp.i(201),'2026-09-01','google_ads','1111111111','USD','fixture',100,10,1.01,0.125);
create function pg_temp.filters()returns jsonb language sql immutable as $$select'{"startDate":"2026-09-01","endDate":"2026-09-30","channel":null,"account":null,"compare":false}'::jsonb$$;
create function pg_temp.plan()returns jsonb language sql immutable as $$select'{"groupBy":"channel","startDate":"2026-09-01","endDate":"2026-09-30","channel":null}'::jsonb$$;
create function pg_temp.input(mode text default'manual')returns jsonb language sql as $$select jsonb_build_object('operation','request','mode',mode,'question','Retained query fixture','filters',pg_temp.filters(),'sourceHash',public.bi_report_source(pg_temp.i(101),pg_temp.i(201),pg_temp.filters())->'sourceHash')||case when mode='manual'then jsonb_build_object('plan',pg_temp.plan())else'{}'::jsonb end$$;
create function pg_temp.command(n int,input jsonb,a int default 101,result jsonb default null)returns jsonb language sql as $$select public.decide_bi_query(pg_temp.i(n),pg_temp.i(a),pg_temp.i(201),input,result)$$;
create function pg_temp.change_it(n int,q int,kind text,revision int,extra jsonb default'{}',result jsonb default null)returns jsonb language sql as $$select pg_temp.command(n,jsonb_build_object('operation',kind,'queryId',pg_temp.i(q),'expectedRevision',revision)||extra,101,result)$$;
create function pg_temp.read_it(kind text default'list',n int default null,a int default 101,offset_n int default 0)returns jsonb language sql as $$select public.read_bi_queries(pg_temp.i(a),pg_temp.i(201),jsonb_build_object('kind',kind,'id',pg_temp.i(n),'offset',offset_n))$$;
set local role service_role;
select pg_temp.check_it(public.bi_query_plan_valid(pg_temp.plan(),pg_temp.filters()),'bounded plan accepted');
select pg_temp.check_it(not public.bi_query_plan_valid(pg_temp.plan()||'{"sql":"select 1"}',pg_temp.filters()),'SQL never accepted');
select pg_temp.check_it(not public.bi_query_plan_valid(pg_temp.plan()||'{"groupBy":"pg_sleep(1)"}',pg_temp.filters()),'grouping expression denied');
select pg_temp.check_it(not public.bi_query_plan_valid(pg_temp.plan()||'{"limit":100}',pg_temp.filters()),'silent truncation denied');
select pg_temp.check_it(not public.bi_query_plan_valid(pg_temp.plan()||'{"startDate":"2026-02-30"}',pg_temp.filters()),'invalid date denied');
select pg_temp.check_it(not public.bi_query_plan_valid(pg_temp.plan()||'{"startDate":"2026-08-01"}',pg_temp.filters()),'source period cannot widen');
select pg_temp.check_it(not public.bi_query_plan_valid(pg_temp.plan()||'{"channel":"meta_ads"}',pg_temp.filters()||'{"channel":"google_ads"}'),'source channel cannot widen');
select pg_temp.check_it(pg_temp.command(301,pg_temp.input())->>'status'='review','manual request captures source for review');
select pg_temp.check_it(pg_temp.command(301,pg_temp.input())->>'state'='replayed','lost request replay exact');
select pg_temp.check_it(pg_temp.command(301,pg_temp.input()||'{"question":"Changed"}')->>'state'='request_conflict','question cannot change on replay');
select pg_temp.check_it(pg_temp.command(301,pg_temp.input(),104)->>'state'='not_found','other actor cannot claim identity');
select pg_temp.check_it(pg_temp.command(302,pg_temp.input(),103)->>'state'='forbidden','other org denied');
select pg_temp.check_it(pg_temp.command(302,pg_temp.input(),102)->>'status'='review','viewer can calculate own private report');
select pg_temp.check_it(pg_temp.read_it('detail',301,104)->>'state'='not_found','query is private within property');
select pg_temp.check_it(pg_temp.read_it('list',null,102)->>'count'='1','viewer sees only own query');
select pg_temp.check_it(pg_temp.read_it('list',null,103)->>'state'='forbidden','other org cannot list');
insert into st values('source',pg_temp.read_it('detail',301)),('input',pg_temp.input());
update public.fact_marketing_performance set spend=5 where property_id=pg_temp.i(201);
select pg_temp.check_it(pg_temp.command(303,(select v from st where k='input'))->>'state'='source_changed','stale current report cannot capture new figures');
select pg_temp.check_it(pg_temp.read_it('detail',301)#>>'{query,source,currentRows,0,spend}'='1.01','saved source remains original after import');
select pg_temp.check_it(pg_temp.change_it(303,301,'revise',9,jsonb_build_object('plan',pg_temp.plan()))->>'state'='query_changed','stale plan revision held');
select pg_temp.check_it(pg_temp.change_it(303,301,'revise',1,jsonb_build_object('plan',pg_temp.plan()||'{"groupBy":"campaign"}'))->>'revision'='2','reviewed plan correction retained');
select pg_temp.check_it(pg_temp.read_it('history',301)#>>'{items,1,before,plan,groupBy}'='channel','correction retains prior plan');
select pg_temp.check_it(pg_temp.change_it(304,301,'execute',2,jsonb_build_object('planHash',repeat('0',64)),'{}')->>'state'='query_changed','different plan cannot execute');
select pg_temp.check_it(pg_temp.change_it(304,301,'execute',2,jsonb_build_object('planHash',public.knowledge_hash(pg_temp.plan()||'{"groupBy":"campaign"}')),'{}')->>'state'='invalid_result','missing result lineage rejected');
insert into st values('result',(select jsonb_build_object('definitionVersion','bi-query-v1','sourceHash',source_hash,'planHash',plan_hash,'rows',(select jsonb_agg(jsonb_build_object('key',n,'clicks',n))from generate_series(1,51)n))from public.bi_queries where id=pg_temp.i(301)));
select pg_temp.check_it(pg_temp.change_it(304,301,'execute',2,jsonb_build_object('planHash',public.knowledge_hash(pg_temp.plan()||'{"groupBy":"campaign"}')),(select v from st where k='result'))->>'status'='complete','calculation retained once');
select pg_temp.check_it(pg_temp.change_it(304,301,'execute',2,jsonb_build_object('planHash',public.knowledge_hash(pg_temp.plan()||'{"groupBy":"campaign"}')),null)->>'state'='replayed','lost calculation result recovers without recalculation');
select pg_temp.check_it(pg_temp.read_it('rows',301)->>'count'='51'and jsonb_array_length(pg_temp.read_it('rows',301)->'items')=25,'complete count and bounded first results page');
select pg_temp.check_it(jsonb_array_length(pg_temp.read_it('rows',301,101,25)->'items')=25,'second results page complete');
select pg_temp.check_it(jsonb_array_length(pg_temp.read_it('rows',301,101,50)->'items')=1,'final result reachable');
select pg_temp.check_it(pg_temp.change_it(305,301,'revise',3,jsonb_build_object('plan',pg_temp.plan()))->>'state'='closed_query','completed calculation cannot be rewritten');
select pg_temp.check_it(pg_temp.command(305,'{"operation":"cancel_request"}')->>'status'='cancelled_request','unused decision tombstone retained');
select pg_temp.check_it(pg_temp.command(305,pg_temp.input())->>'status'='cancelled_request','late request fenced');
select pg_temp.check_it(pg_temp.command(301,'{"operation":"cancel_request"}')->>'queryId'=pg_temp.i(301)::text,'cancellation cannot erase prepared query');
select pg_temp.check_it(pg_temp.command(306,pg_temp.input('assistant'))->>'status'='requested','interpretation request is separate from result');
select pg_temp.check_it(public.claim_bi_query(pg_temp.i(306),pg_temp.i(501))->>'state'='started','one model claim recorded before invocation');
select pg_temp.check_it(public.claim_bi_query(pg_temp.i(306),pg_temp.i(501))->>'state'='not_started','lost model claim never authorizes retry');
select pg_temp.check_it(public.claim_bi_query(pg_temp.i(306),pg_temp.i(502))->>'state'='not_started','second worker fenced');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(502),jsonb_build_object('plan',pg_temp.plan(),'issue',null))->>'state'='claim_conflict','wrong model token fenced');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(501),jsonb_build_object('plan',pg_temp.plan(),'issue',null)||'{"model":{"bad":true}}')->>'state'='invalid_input','malformed model metadata denied');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(501),jsonb_build_object('plan',pg_temp.plan(),'issue',null)||'{"providerId":[1]}')->>'state'='invalid_input','malformed model metadata denied');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(501),jsonb_build_object('plan',pg_temp.plan(),'issue',null)||'{"raw":{"text":"hidden"}}')->>'state'='invalid_input','malformed model metadata denied');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(501),jsonb_build_object('plan',pg_temp.plan(),'issue',null)||'{"rawOmitted":"false"}')->>'state'='invalid_input','malformed model metadata denied');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(501),jsonb_build_object('plan',pg_temp.plan(),'issue',null)||'{"rawSha256":"bad"}')->>'state'='invalid_input','malformed model metadata denied');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(501),jsonb_build_object('plan',pg_temp.plan(),'issue',null)||'{"usage":{"cost":5}}')->>'state'='invalid_input','malformed model metadata denied');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(501),jsonb_build_object('plan',pg_temp.plan(),'issue',null)||'{"usage":{"inputTokens":-1}}')->>'state'='invalid_input','malformed model metadata denied');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(501),jsonb_build_object('plan',pg_temp.plan(),'issue',null)||'{"usage":{"inputTokens":1.5}}')->>'state'='invalid_input','malformed model metadata denied');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(501),jsonb_build_object('plan',pg_temp.plan(),'issue',null,'raw',pg_temp.plan()::text,'providerId','synthetic-receipt','model','fixture-model','usage',jsonb_build_object('totalTokens',15)))->>'status'='review','actual model plan needs human review');
select pg_temp.check_it(pg_temp.read_it('detail',306)#>>'{interpretation,providerId}'='synthetic-receipt','safe model identity visible');
select pg_temp.check_it(not(pg_temp.read_it('detail',306)->'query'?'claim_token')and not(pg_temp.read_it('detail',306)->'interpretation'?'raw'),'claim and private raw model reply omitted from reads');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(501),jsonb_build_object('plan',pg_temp.plan(),'issue',null,'raw',pg_temp.plan()::text,'providerId','synthetic-receipt','model','fixture-model','usage',jsonb_build_object('totalTokens',15)))->>'state'='replayed','exact model receipt replay');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(306),pg_temp.i(501),'{"issue":"provider_unknown"}')->>'state'='request_conflict','model receipt immutable');
select pg_temp.command(307,pg_temp.input('assistant'));select public.claim_bi_query(pg_temp.i(307),pg_temp.i(503));
select pg_temp.check_it(pg_temp.change_it(308,307,'stop',2)->>'status'='cancelled','stop recorded while model in flight');
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(307),pg_temp.i(503),jsonb_build_object('plan',pg_temp.plan(),'issue',null))->>'status'='cancelled','late model receipt never revives stopped query');
select pg_temp.check_it((select model_receipt is not null and plan is null from public.bi_queries where id=pg_temp.i(307)),'late result retained but never adopted');
select pg_temp.command(309,pg_temp.input('assistant'));select public.claim_bi_query(pg_temp.i(309),pg_temp.i(504));
select pg_temp.check_it(pg_temp.change_it(310,309,'revise',2,jsonb_build_object('plan',pg_temp.plan()||'{"groupBy":"day"}'))->>'status'='review','operator can replace unresolved interpretation with manual plan');
select public.prepare_bi_query(pg_temp.i(309),pg_temp.i(504),jsonb_build_object('plan',pg_temp.plan(),'issue',null));
select pg_temp.check_it(pg_temp.read_it('detail',309)#>>'{query,plan,groupBy}'='day','late model cannot overwrite reviewed correction');
select pg_temp.command(311,pg_temp.input('assistant'));select public.claim_bi_query(pg_temp.i(311),pg_temp.i(505));
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(311),pg_temp.i(505),'{"plan":null,"issue":"provider_unknown","raw":null}')->>'status'='held','provider uncertainty retained separately');
select pg_temp.check_it(public.claim_bi_query(pg_temp.i(311),pg_temp.i(506))->>'state'='not_started','uncertain provider result never retried');
select pg_temp.command(312,pg_temp.input('assistant'));select public.claim_bi_query(pg_temp.i(312),pg_temp.i(506));
select pg_temp.check_it(public.prepare_bi_query(pg_temp.i(312),pg_temp.i(506),jsonb_build_object('plan',pg_temp.plan()||'{"sql":"select 1"}','issue',null))->>'status'='held','unsafe model shape never approved');
select pg_temp.check_it((select bool_and(service_principal='bi.query_interpreter'and actor_id is null)from public.shared_action_events where property_id=pg_temp.i(201)and action like'bi.query.interpretation%'),'system invocation uses actual service principal');
select pg_temp.check_it((select bool_and(not training_eligible)from public.shared_action_events where property_id=pg_temp.i(201)),'all events remain training ineligible');
select pg_temp.check_it((select count(*)from public.bi_query_commands where property_id=pg_temp.i(201))=(select count(*)from public.shared_action_events where property_id=pg_temp.i(201)and actor_id is not null),'one atomic human event per decision');
select set_config('p11.bi_query_scope','',true);
select pg_temp.throws(format('update public.bi_queries set state=%L where id=%L','review',pg_temp.i(301)),'service cannot bypass recorded control');
select pg_temp.throws(format('delete from public.bi_queries where id=%L',pg_temp.i(301)),'live query retention cannot be bypassed');
select set_config('p11.bi_query_scope',pg_temp.i(201)::text,true);
select pg_temp.throws(format('update public.bi_queries set source=%L where id=%L','{}',pg_temp.i(301)),'source snapshot immutable');
select pg_temp.throws(format('update public.bi_queries set result=%L where id=%L','{}',pg_temp.i(301)),'complete result immutable');
select pg_temp.throws(format('update public.bi_query_commands set result=%L where id=%L','{}',pg_temp.i(301)),'command history immutable');
insert into st values('list',pg_temp.read_it());
select pg_temp.command(313,pg_temp.input('assistant'));
select pg_temp.check_it(public.read_bi_queries(pg_temp.i(101),pg_temp.i(201),jsonb_build_object('expectedHash',(select v->>'hash'from st where k='list')))->>'state'='history_changed','history page changed fence');
reset role;
select pg_temp.check_it(not has_table_privilege('authenticated','public.bi_queries','SELECT'),'private source table service-only');
select pg_temp.check_it(not has_function_privilege('authenticated','public.decide_bi_query(uuid,uuid,uuid,jsonb,jsonb)','EXECUTE'),'decision function service-only');
select set_config('p11.team_scope',pg_temp.i(1)::text,true);update public.profiles set org_id=null,role='viewer'where id=pg_temp.i(101);
select pg_temp.check_it(pg_temp.read_it('detail',301)->>'state'='forbidden','membership revoked before saved read');
select pg_temp.check_it(pg_temp.command(301,(select v from st where k='input'))->>'state'='forbidden','membership revoked before replay');
select pg_temp.check_it(public.claim_bi_query(pg_temp.i(313),pg_temp.i(510))->>'state'='not_started','removed author cannot start model');
select n as assertions_passed from assertion_count;
ROLLBACK;
